require_once __DIR__.'/../includes/auth.php';$admin=require_admin();$id=(int)($_GET['id']??0);$stmt=db()->prepare('SELECT * FROM cases WHERE id=? AND deleted_at IS NULL');$stmt->execute([$id]);$c=$stmt->fetch();if(!$c){http_response_code(404);exit('Not found');}$public=base_url('track.php?code='.urlencode($c['case_code']));audit($admin['id'],'print_idcard',$id);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>ID <?=e($c['case_code'])?></title><link rel="stylesheet" href="<?=e(base_url('assets/app.css'))?>"><style>.idcard{width:148mm;min-height:105mm;margin:15px auto;background:#fff;border:2px solid #0b5cab;border-radius:16px;padding:10mm;position:relative}.idgrid{display:grid;grid-template-columns:42mm 1fr 30mm;gap:8mm}.idphoto{width:42mm;height:52mm;object-fit:cover;border-radius:10px;background:#eef2f6}.qr{width:30mm;height:30mm}.bigcode{font-size:20px;font-weight:800;color:#0b5cab}@media print{.idcard{margin:0;border:1px solid #444;break-inside:avoid}}</style></head><body><div class="no-print" style="max-width:148mm;margin:15px auto"><button class="btn btn-primary" onclick="window.print()">Print / Save PDF</button></div><div class="idcard"><h2 style="margin-top:0"><?=e(case_type_label($c['type']))?> • Rescue Nepal Case ID</h2><div class="bigcode"><?=e($c['case_code'])?></div><div class="idgrid" style="margin-top:10px"><div><?php if($c['photo_url']): $idPhotoUrl=$c['type']==='deceased'?base_url('admin/media/dvi/'.$id):base_url($c['photo_url']);?><img class="idphoto" src="<?=e($idPhotoUrl)?>"><?php else:?><div class="idphoto"></div><?php endif;?></div><div><b><?=e($c['name'])?></b><br><?=e($c['age']!==null?'Age '.$c['age'].' • ':'')?><?=e($c['gender'])?><p><b>Last Seen / अन्तिम स्थान</b><br><?=e($c['current_location']?:($c['where_found']?:($c['last_seen_address']?:$c['from_location'])))?></p><p><b>Contact / सम्पर्क</b><br><?=e($c['family_contact_name'])?><br><?=e($c['family_contact_phone'])?></p><span class="status status-<?=e($c['status'])?>"><?=e(case_status_label($c['status']))?></span><?php if($c['current_condition']):?> <span class="condition condition-<?=e($c['current_condition'])?>"><?=e(case_condition_label($c['current_condition']))?></span><?php endif;?></div><div id="qrcode" class="qr"></div></div><p class="small muted">Scan QR to view the public case status.</p></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>new QRCode(document.getElementById('qrcode'),{text:<?=json_encode($public)?>,width:112,height:112});</script></body></html>
